1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Scenario {
6	  customer: Customer;
7	  steps: Step[];
8	}
9	
10	export type Step = QuoteStep | ClaimStep;
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Item {
18	  type: string;
19	  material?: string;
20	  enchantment?: number;
21	  cursed?: boolean;
22	}
23	
24	export interface ClaimStep {
25	  op: "claim";
26	  policy: number;
27	  incident: Incident;
28	}
29	
30	export interface Incident {
31	  cause: string;
32	  damages: Damage[];
33	}
34	
35	export interface Damage {
36	  itemType: string;
37	  amount: number;
38	}
39	
40	export type Result = QuoteResult | ClaimResult;
41	
42	export interface QuoteResult {
43	  premium: number;
44	}
45	
46	export interface ClaimResult {
47	  payout: number;
48	  remainingCap: number;
49	}
50	
51	export interface ScenarioResult {
52	  results: Result[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	const FIRST_INSURANCE_SURCHARGE_RATE = 1 / 10;
57	// Base premium for a single item of each type.
58	const UNIT_BASE_PREMIUMS: Record<string, number> = {
59	  sword: 100,
60	  amulet: 60,
61	  staff: 80,
62	  potion: 40,
63	  rune: 25,
64	  moonstone: 25,
65	};
66	
67	// Insurance value of a single item of each type.
68	const UNIT_INSURANCE_VALUES: Record<string, number> = {
69	  sword: 1000,
70	  amulet: 600,
71	  staff: 800,
72	  potion: 400,
73	  rune: 250,
74	  moonstone: 250,
75	};
76	
77	const LOYALTY_YEARS_THRESHOLD = 2;
78	const LOYALTY_DISCOUNT_RATE = 2 / 10;
79	const FOLLOW_UP_DISCOUNT_RATE = 15 / 100;
80	const CURSE_SURCHARGE_RATE = 1 / 2;
81	const HIGH_ENCHANTMENT_THRESHOLD = 5;
82	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 3 / 10;
83	const BLOCK_SIZE = 3;
84	const BLOCK_BASE_PREMIUM = 60;
85	const DEDUCTIBLE = 100;
86	const CAP_MULTIPLIER = 2;
87	const REDUCED_REIMBURSEMENT_THRESHOLD = 8;
88	const REDUCED_REIMBURSEMENT_RATE = 1 / 2;
89	
90	const unitBasePremium = (type: string): number => UNIT_BASE_PREMIUMS[type];
91	
92	const countByType = (items: Item[]): Map<string, number> =>
93	  items.reduce(
94	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
95	    new Map<string, number>(),
96	  );
97	
98	// A building block of 3 alike components is offered at a special base premium.
99	const basePremiumForItemGroup = (type: string, count: number): number =>
100	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * unitBasePremium(type);
101	
102	const policyBasePremium = (items: Item[]): number =>
103	  [...countByType(items)].reduce(
104	    (total, [type, count]) => total + basePremiumForItemGroup(type, count),
105	    0,
106	  );
107	
108	const isHighlyEnchanted = (item: Item): boolean =>
109	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
110	
111	const surchargeRate = (item: Item): number =>
112	  (item.cursed ? CURSE_SURCHARGE_RATE : 0) +
113	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_RATE : 0);
114	
115	// Item-specific modifiers apply to the affected item's own base premium, i.e.
116	// the unit price of its type — a block discount never shrinks a surcharge.
117	const itemSurcharge = (item: Item): number =>
118	  unitBasePremium(item.type) * surchargeRate(item);
119	
120	const itemSurcharges = (items: Item[]): number =>
121	  items.reduce((total, item) => total + itemSurcharge(item), 0);
122	
123	const isLongStanding = (customer: Customer): boolean =>
124	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
125	
126	// Policy-wide modifiers apply to the policy base premium only — never to the
127	// item surcharges. Net signed delta: a discount can outweigh the surcharge.
128	// Every quote is a first insurance for its items, regardless of customer
129	// history, so that surcharge always applies.
130	const policyAdjustmentRate = (
131	  customer: Customer,
132	  isFollowUpContract: boolean,
133	): number =>
134	  FIRST_INSURANCE_SURCHARGE_RATE -
135	  (isLongStanding(customer) ? LOYALTY_DISCOUNT_RATE : 0) -
136	  (isFollowUpContract ? FOLLOW_UP_DISCOUNT_RATE : 0);
137	
138	// Premiums round up, in the MHPCO's favour. The adjustment is added as a
139	// separate term rather than folded into a `base * 1.1` factor, which is not
140	// exact in binary floating point (100 * 1.1 === 110.00000000000001).
141	const quotePremium = (
142	  items: Item[],
143	  customer: Customer,
144	  isFollowUpContract: boolean,
145	): number => {
146	  const base = policyBasePremium(items);
147	  return Math.ceil(
148	    base +
149	      itemSurcharges(items) +
150	      base * policyAdjustmentRate(customer, isFollowUpContract) +
151	      PROCESSING_FEE,
152	  );
153	};
154	
155	const unitInsuranceValue = (type: string): number =>
156	  UNIT_INSURANCE_VALUES[type];
157	
158	// The total payout per policy is capped at twice the insurance sum. Premium
159	// modifiers never reach the insurance sum: it is the plain sum of the unit
160	// values of the insured items.
161	const insuranceSum = (items: Item[]): number =>
162	  items.reduce((sum, item) => sum + unitInsuranceValue(item.type), 0);
163	
164	// A policy created by a quote step, tracked so later claims can pay out
165	// against it. `remainingCap` shrinks as successive claims are settled.
166	interface Policy {
167	  items: Item[];
168	  remainingCap: number;
169	}
170	
171	const openPolicy = (items: Item[]): Policy => ({
172	  items,
173	  remainingCap: CAP_MULTIPLIER * insuranceSum(items),
174	});
175	
176	// State accumulated by the steps run so far. Later steps price and pay out
177	// against what earlier steps established, so each step reads the state it was
178	// run with and returns the state the next step should see.
179	interface ScenarioState {
180	  customer: Customer;
181	  contractsSoFar: number;
182	  // Keyed by the zero-based index of the quote step that created the policy.
183	  policies: Map<number, Policy>;
184	}
185	
186	// A step's outcome: what to report, and how the scenario stands afterwards.
187	interface StepOutcome {
188	  result: Result;
189	  state: ScenarioState;
190	}
191	
192	// Records a policy against the step index that identifies it, leaving the
193	// state it was given untouched.
194	const withPolicy = (
195	  state: ScenarioState,
196	  policyId: number,
197	  policy: Policy,
198	): ScenarioState => ({
199	  ...state,
200	  policies: new Map(state.policies).set(policyId, policy),
201	});
202	
203	const quote = (
204	  step: QuoteStep,
205	  state: ScenarioState,
206	  stepIndex: number,
207	): StepOutcome => ({
208	  result: {
209	    premium: quotePremium(step.items, state.customer, state.contractsSoFar > 0),
210	  },
211	  state: withPolicy(
212	    { ...state, contractsSoFar: state.contractsSoFar + 1 },
213	    stepIndex,
214	    openPolicy(step.items),
215	  ),
216	});
217	
218	const isFragilelyEnchanted = (item: Item): boolean =>
219	  (item.enchantment ?? 0) >= REDUCED_REIMBURSEMENT_THRESHOLD;
220	
221	// Damage to highly enchanted items is reimbursed at 50 % of the damage amount.
222	const reimbursementRate = (item: Item): number =>
223	  isFragilelyEnchanted(item) ? REDUCED_REIMBURSEMENT_RATE : 1;
224	
225	// A deductible applies per damage event, i.e. once per damaged item. Special
226	// clauses reduce the reimbursement first; the deductible comes off after.
227	const damagePayout = (damage: Damage, item: Item): number =>
228	  damage.amount * reimbursementRate(item) - DEDUCTIBLE;
229	
230	const claim = (step: ClaimStep, state: ScenarioState): StepOutcome => {
231	  const policy = state.policies.get(step.policy)!;
232	  const payout = step.incident.damages.reduce(
233	    (total, damage) =>
234	      total +
235	      damagePayout(damage, policy.items.find((i) => i.type === damage.itemType)!),
236	    0,
237	  );
238	  const remainingCap = policy.remainingCap - payout;
239	  return {
240	    result: { payout, remainingCap },
241	    state: withPolicy(state, step.policy, { ...policy, remainingCap }),
242	  };
243	};
244	
245	const runStep = (
246	  step: Step,
247	  state: ScenarioState,
248	  stepIndex: number,
249	): StepOutcome => {
250	  switch (step.op) {
251	    case "quote":
252	      return quote(step, state, stepIndex);
253	    case "claim":
254	      return claim(step, state);
255	  }
256	};
257	
258	export const runScenario = (scenario: Scenario): ScenarioResult => {
259	  const initialState: ScenarioState = {
260	    customer: scenario.customer,
261	    contractsSoFar: 0,
262	    policies: new Map(),
263	  };
264	  const { results } = scenario.steps.reduce<{
265	    results: Result[];
266	    state: ScenarioState;
267	  }>(
268	    ({ results, state }, step, stepIndex) => {
269	      const outcome = runStep(step, state, stepIndex);
270	      return { results: [...results, outcome.result], state: outcome.state };
271	    },
272	    { results: [], state: initialState },
273	  );
274	  return { results };
275	};
